'use client'

import { FormEvent, useCallback, useEffect, useMemo, useState } from 'react'
import { fetchApi } from '../services/api'

type Session = { correo: string; roles: string[] }
type LoginResponse = Session & { accessToken: string; tokenType: string }
type Solicitud = { idSolicitud: number; codigoSolicitud: string; nombreCliente?: string; tipoServicio?: string; direccionInstalacion?: string; fechaSolicitud?: string; estado?: string }
type Orden = { idOrden: number; codigoOrden: string; idSolicitud?: number; codigoSolicitud?: string; idTecnico?: number; nombreTecnico?: string; fechaProgramada?: string; horaProgramada?: string; fechaInicio?: string; fechaFinalizacion?: string; estado?: string; observaciones?: string }
type Tecnico = { idTecnico: number; idUsuario?: number; nombres: string; apellidos: string; correo?: string; telefono?: string; especialidad?: string; disponibilidad?: boolean; estado?: boolean }
type Dispositivo = { idDispositivo: number; idTipoDispositivo?: number; tipoDispositivo?: string; marca?: string; modelo?: string; numeroSerie?: string; estado?: string; disponibilidad?: boolean }
type Evidencia = { idEvidencia: number; idOrden: number; codigoOrden?: string; nombreArchivo?: string; urlArchivo?: string; descripcion?: string; fechaRegistro?: string; estadoValidacion?: string; observacionValidacion?: string }
type Cliente = { idCliente: number; idUsuario?: number; nombres: string; apellidos: string; correo: string; telefono?: string; tipoDocumento?: string; numeroDocumento?: string; razonSocial?: string; direccion?: string; estado?: boolean }
type Coordinador = { idCoordinador: number; nombres: string; apellidos: string; correo: string; cargo?: string; estado?: boolean }
type Usuario = { idUsuario: number; idRol: number; rol: string; nombres: string; apellidos: string; correo: string; estado?: boolean }
type TipoDispositivo = { idTipoDispositivo: number; nombre: string; descripcion?: string; estado?: boolean }
type Historial = { idHistorial: number; codigoOrden: string; nombreUsuario?: string; tipoEvento: string; estadoAnterior?: string; estadoNuevo?: string; fechaHora: string; motivo?: string }
type OrdenDispositivo = { idOrdenDispositivo: number; idOrden: number; idDispositivo: number; numeroSerie: string; tipoDispositivo?: string; marca?: string; modelo?: string; estadoAsignacion?: string; observaciones?: string }
type Observacion = { idObservacion: number; idOrden: number; idTecnico?: number; nombreTecnico?: string; descripcion: string; fechaRegistro?: string; estado?: boolean }
type SeguimientoResultado = { codigoConsultado: string; codigoSolicitud: string; codigoOrden?: string; tipoServicio?: string; fechaSolicitud?: string; fechaProgramada?: string; horaProgramada?: string; estadoSolicitud?: string; estadoOrden?: string; estadoActual?: string; etapaActual?: string; nombreTecnico?: string }
type ProfileKind = 'CLIENTE' | 'TECNICO' | 'COORDINADOR'
type View = 'dashboard' | 'solicitudes' | 'ordenes' | 'programacion' | 'evidencias' | 'inventario' | 'personas' | 'historial' | 'seguimiento'

const nav: Array<{ id: View; label: string; icon: string }> = [
  { id: 'dashboard', label: 'Dashboard', icon: '▦' }, { id: 'solicitudes', label: 'Solicitudes', icon: '□' },
  { id: 'ordenes', label: 'Órdenes', icon: '⚒' }, { id: 'programacion', label: 'Programación', icon: '◷' },
  { id: 'evidencias', label: 'Evidencias', icon: '◫' }, { id: 'inventario', label: 'Equipos / Inventario', icon: '▣' },
  { id: 'personas', label: 'Personas y accesos', icon: '♙' },
  { id: 'historial', label: 'Historial y trazabilidad', icon: '≋' },
  { id: 'seguimiento', label: 'Seguimiento', icon: '⌕' },
]
const friendlyDate = (value?: string) => value ? new Intl.DateTimeFormat('es-PE', { dateStyle: 'medium' }).format(new Date(value)) : 'Sin programar'
const initials = (value = '') => value.split('@')[0].slice(0, 2).toUpperCase()
const statusLabel = (value?: string | boolean) => typeof value === 'boolean' ? (value ? 'Disponible' : 'No disponible') : (value || 'Sin estado')
const statusTone = (value?: string | boolean) => { const v = statusLabel(value).toUpperCase(); return v.includes('COMPLE') || v.includes('CERR') || v.includes('APROB') || v.includes('VALID') || v === 'DISPONIBLE' ? 'success' : v.includes('PROCES') || v.includes('ASIGN') || v.includes('PROGRAM') ? 'info' : v.includes('PEND') || v.includes('EVAL') || v.includes('NO DISPONIBLE') ? 'warning' : 'neutral' }

export default function Home() {
  const [session, setSession] = useState<Session | null>(null); const [view, setView] = useState<View>('dashboard')
  const [solicitudes, setSolicitudes] = useState<Solicitud[]>([]); const [ordenes, setOrdenes] = useState<Orden[]>([]); const [tecnicos, setTecnicos] = useState<Tecnico[]>([]); const [dispositivos, setDispositivos] = useState<Dispositivo[]>([]); const [evidencias, setEvidencias] = useState<Evidencia[]>([])
  const [clientes, setClientes] = useState<Cliente[]>([]); const [coordinadores, setCoordinadores] = useState<Coordinador[]>([]); const [usuarios, setUsuarios] = useState<Usuario[]>([])
  const [tiposDispositivo, setTiposDispositivo] = useState<TipoDispositivo[]>([]); const [historial, setHistorial] = useState<Historial[]>([])
  const [loading, setLoading] = useState(false); const [notice, setNotice] = useState(''); const [error, setError] = useState('')
  const [showLogin, setShowLogin] = useState(false); const [showSolicitud, setShowSolicitud] = useState(false); const [showEvidence, setShowEvidence] = useState(false); const [showProgramacion, setShowProgramacion] = useState(false); const [showProfile, setShowProfile] = useState(false); const [profileKind, setProfileKind] = useState<ProfileKind>('CLIENTE'); const [tracking, setTracking] = useState<SeguimientoResultado | null>(null)
  const isCoordinator = session?.roles.some((role) => role.includes('COORDINADOR') || role.includes('ADMINISTRADOR')) ?? false
  const isCoordinatorRole = session?.roles.some((role) => role.includes('COORDINADOR')) ?? false
  const isAdmin = session?.roles.some((role) => role.includes('ADMINISTRADOR')) ?? false
  const isTecnico = session?.roles.some((role) => role.includes('TECNICO')) ?? false
  const isCliente = session?.roles.some((role) => role.includes('CLIENTE')) ?? false
  const visibleNav = useMemo(() => nav.filter((item) => {
    if (!session) return item.id === 'dashboard' || item.id === 'seguimiento'
    if (isAdmin) return true
    if (isCoordinator) return !['personas', 'historial'].includes(item.id)
    if (isTecnico) return ['dashboard', 'ordenes', 'evidencias', 'seguimiento'].includes(item.id)
    return ['dashboard', 'solicitudes', 'seguimiento'].includes(item.id)
  }), [session, isAdmin, isCoordinator, isTecnico])
  const roleName = useMemo(() => session?.roles[0]?.replace('ROLE_', '').replaceAll('_', ' ') || 'Invitado', [session])
  const showMessage = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 5000) }
  const loadData = useCallback(async () => {
    if (!session) return
    setLoading(true); setError('')
    try {
      if (isCliente) {
        setSolicitudes(await fetchApi<Solicitud[]>('/solicitudes/mis-solicitudes'))
      } else if (isTecnico) {
        const techOrders=await fetchApi<Orden[]>('/ordenes/mis-ordenes'); setOrdenes(techOrders)
        setDispositivos(await fetchApi<Dispositivo[]>('/dispositivos'))
        const evidenceGroups=await Promise.all(techOrders.map(order=>fetchApi<Evidencia[]>('/evidencias/orden/'+order.idOrden))); setEvidencias(evidenceGroups.flat())
      } else {
        const [sol, ord, tec, disp, evid] = await Promise.all([fetchApi<Solicitud[]>('/solicitudes'), fetchApi<Orden[]>('/ordenes'), fetchApi<Tecnico[]>('/tecnicos'), fetchApi<Dispositivo[]>('/dispositivos'), fetchApi<Evidencia[]>('/evidencias')])
        setSolicitudes(sol); setOrdenes(ord); setTecnicos(tec); setDispositivos(disp); setEvidencias(evid)
        if (isAdmin) {
          const [cli, coord, users, tipos, history] = await Promise.all([fetchApi<Cliente[]>('/clientes'), fetchApi<Coordinador[]>('/coordinadores'), fetchApi<Usuario[]>('/usuarios'), fetchApi<TipoDispositivo[]>('/tipos-dispositivo'), fetchApi<Historial[]>('/historial-ordenes')])
          setClientes(cli); setCoordinadores(coord); setUsuarios(users); setTiposDispositivo(tipos); setHistorial(history)
        }
      }
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : 'No fue posible cargar los datos del sistema.')
    } finally { setLoading(false) }
  }, [session, isAdmin, isCliente, isTecnico])
  useEffect(() => { const task=window.setTimeout(()=>{const token = localStorage.getItem('fiberperu_token'); const stored = localStorage.getItem('fiberperu_session'); if (token && stored) try { setSession(JSON.parse(stored) as Session) } catch { localStorage.removeItem('fiberperu_session') }},0);return()=>window.clearTimeout(task) }, [])
  useEffect(() => { const task=window.setTimeout(()=>void loadData(),0);return()=>window.clearTimeout(task) }, [loadData])
  const login = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); setError(''); try { const response = await fetchApi<LoginResponse>('/auth/login', { method: 'POST', body: JSON.stringify({ correo: form.get('correo'), password: form.get('password') }) }); const next = { correo: response.correo, roles: response.roles }; localStorage.setItem('fiberperu_token', response.accessToken); localStorage.setItem('fiberperu_session', JSON.stringify(next)); setSession(next); setShowLogin(false); showMessage('Sesión iniciada correctamente. Se cargaron los módulos autorizados para tu rol.') } catch (e) { setError(e instanceof Error ? e.message : 'No fue posible iniciar sesión.') } }
  const logout = () => { localStorage.removeItem('fiberperu_token'); localStorage.removeItem('fiberperu_session'); setSession(null); setSolicitudes([]); setOrdenes([]); setTecnicos([]); setDispositivos([]); setEvidencias([]); setView('dashboard'); showMessage('Sesión cerrada.') }
  const createSolicitud = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); try { await fetchApi('/solicitudes', { method: 'POST', body: JSON.stringify({ idCliente: isCliente ? null : Number(f.get('idCliente')), codigoSolicitud: f.get('codigoSolicitud'), tipoServicio: f.get('tipoServicio'), descripcionServicio: f.get('descripcionServicio'), direccionInstalacion: f.get('direccionInstalacion') }) }); setShowSolicitud(false); showMessage('Solicitud registrada y enviada al backend.'); void loadData() } catch (e) { setError(e instanceof Error ? e.message : 'No fue posible registrar la solicitud.') } }
  const scheduleOrder = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const id = Number(f.get('idOrden')); try { await fetchApi(`/ordenes/${id}/tecnico`, { method: 'PATCH', body: JSON.stringify({ idTecnico: Number(f.get('idTecnico')) }) }); await fetchApi(`/ordenes/${id}/programacion`, { method: 'PATCH', body: JSON.stringify({ fechaProgramada: f.get('fechaProgramada'), horaProgramada: f.get('horaProgramada') }) }); setShowProgramacion(false); showMessage('Técnico y programación actualizados.'); void loadData() } catch (e) { setError(e instanceof Error ? e.message : 'No fue posible programar la orden.') } }
  const createEvidence = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); try { await fetchApi('/evidencias/archivo', { method: 'POST', body: f }); setShowEvidence(false); showMessage('Archivo almacenado en Azure y evidencia registrada para validación.'); void loadData() } catch (e) { setError(e instanceof Error ? e.message : 'No fue posible registrar la evidencia.') } }
  const createProfile = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const f = new FormData(event.currentTarget)
    const roleName = `ROLE_${profileKind}`
    const roleId = usuarios.find((user) => user.rol === roleName)?.idRol
    if (!roleId) { setError(`No se encontró el rol ${roleName} en los usuarios registrados.`); return }
    const usuario = { idRol: roleId, nombres: f.get('nombres'), apellidos: f.get('apellidos'), correo: f.get('correo'), password: f.get('password'), telefono: f.get('telefono') }
    const payload = profileKind === 'CLIENTE' ? { usuario, tipoDocumento: f.get('tipoDocumento'), numeroDocumento: f.get('numeroDocumento'), razonSocial: f.get('razonSocial'), direccion: f.get('direccion') } : profileKind === 'TECNICO' ? { usuario, especialidad: f.get('especialidad') } : { usuario, cargo: f.get('cargo') }
    const endpoint = profileKind === 'CLIENTE' ? '/clientes' : profileKind === 'TECNICO' ? '/tecnicos' : '/coordinadores'
    try { await fetchApi(endpoint, { method: 'POST', body: JSON.stringify(payload) }); setShowProfile(false); showMessage(`${profileKind.toLowerCase()} registrado correctamente.`); void loadData() } catch (e) { setError(e instanceof Error ? e.message : 'No fue posible registrar la persona.') }
  }
  const searchOrder = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const code = String(new FormData(event.currentTarget).get('codigo') || '').trim(); if (!code) return; try { setTracking(await fetchApi<SeguimientoResultado>(`/public/seguimiento/${encodeURIComponent(code)}`)); setError('') } catch (e) { setTracking(null); setError(e instanceof Error ? e.message : 'No se encontró el código de seguimiento.') } }
  return <main className="app-shell"><aside className="sidebar"><div className="brand"><strong>FIBERPERU E.I.R.L.</strong><span>GESTIÓN DE INSTALACIONES</span></div><nav>{visibleNav.map((item) => <button key={item.id} className={view === item.id ? 'nav-item active' : 'nav-item'} onClick={() => session || item.id === 'seguimiento' ? setView(item.id) : setShowLogin(true)}><i>{item.icon}</i>{item.label}</button>)}</nav><div className="sidebar-footer"><span className="online-dot" /> API REST · Spring Boot</div></aside><section className="workspace"><header className="topbar"><span>Inicio / {visibleNav.find((item) => item.id === view)?.label}</span><div className="profile">{session ? <><span className="avatar">{initials(session.correo)}</span><div><b>{session.correo}</b><small>{roleName}</small></div><button className="text-button" onClick={logout}>Salir</button></> : <button className="primary compact" onClick={() => setShowLogin(true)}>Iniciar sesión</button>}</div></header><div className="content">{notice && <div className="notice success">✓ {notice}</div>}{error && <div className="notice warning">⚠ {error}</div>}{!session && <Welcome onLogin={() => setShowLogin(true)} onTrack={() => setView('seguimiento')} />}{session && view === 'dashboard' && (isCliente?<ClienteDashboard solicitudes={solicitudes} loading={loading} onCreate={()=>setShowSolicitud(true)} onRequests={()=>setView('solicitudes')} onTrack={()=>setView('seguimiento')}/>:<Dashboard solicitudes={solicitudes} ordenes={ordenes} dispositivos={dispositivos} loading={loading} canSchedule={isCoordinator} onNewOrder={() => { setView('programacion'); setShowProgramacion(true) }} />)}{session && view === 'solicitudes' && <Solicitudes solicitudes={solicitudes} ordenes={ordenes} coordinadores={coordinadores} canCreate={isAdmin || isCliente} canEvaluate={isCoordinator} isAdmin={isAdmin} onCreate={() => setShowSolicitud(true)} onUpdated={loadData} />}{session && view === 'ordenes' && <OrdenesAvanzadas ordenes={ordenes} solicitudes={solicitudes} dispositivos={dispositivos} canSchedule={isCoordinator} canOperate={isCoordinator||isTecnico} isTecnico={isTecnico} onSchedule={() => { setView('programacion'); setShowProgramacion(true) }} onUpdated={loadData} />}{session && view === 'programacion' && <Programacion ordenes={ordenes} tecnicos={tecnicos} allowed={isCoordinator} onOpen={() => setShowProgramacion(true)} />}{session && view === 'evidencias' && <Evidencias evidencias={evidencias} canCreate={isAdmin || isTecnico} canValidate={isCoordinatorRole} onCreate={() => setShowEvidence(true)} onUpdated={loadData} />}{session && view === 'inventario' && <AdminInventario dispositivos={dispositivos} tipos={tiposDispositivo} admin={isAdmin} onUpdated={loadData} />}{session && view === 'personas' && isAdmin && <AdminPersonas usuarios={usuarios} clientes={clientes} tecnicos={tecnicos} coordinadores={coordinadores} onUpdated={loadData} onCreate={() => setShowProfile(true)} />}{session && view === 'historial' && isAdmin && <HistorialView historial={historial} solicitudes={solicitudes} ordenes={ordenes} />}{view === 'seguimiento' && <Seguimiento tracking={tracking} onSubmit={searchOrder} />}</div></section>{showLogin && <Modal title="Acceder al sistema" onClose={() => setShowLogin(false)}><form className="form-grid" onSubmit={login}><label>Correo institucional<input required name="correo" type="email" placeholder="usuario@fiberperu.com" /></label><label>Contraseña<input required name="password" type="password" placeholder="••••••••" /></label><button className="primary" type="submit">Ingresar</button></form></Modal>}{showSolicitud && <Modal title="Nueva solicitud de instalación" onClose={() => setShowSolicitud(false)}><form className="form-grid two" onSubmit={createSolicitud}>{!isCliente&&<label>Cliente<select required name="idCliente"><option value="">Seleccionar cliente</option>{clientes.filter(item=>item.estado!==false).map(item=><option key={item.idCliente} value={item.idCliente}>{item.nombres} {item.apellidos} · {item.numeroDocumento}</option>)}</select></label>}<label>Código de solicitud<input required name="codigoSolicitud" placeholder="SOL-2026-0001" /></label><label>Tipo de servicio<select name="tipoServicio"><option>Instalación de internet</option><option>Instalación de red</option><option>Soporte técnico</option></select></label><label>Dirección de instalación<input required name="direccionInstalacion" /></label><label className="full">Descripción del servicio<textarea required name="descripcionServicio" rows={3} /></label><button className="primary" type="submit">Registrar solicitud</button></form></Modal>}{showProgramacion && <Modal title="Programación y asignación" onClose={() => setShowProgramacion(false)}><form className="form-grid two" onSubmit={scheduleOrder}><label>Orden<select required name="idOrden"><option value="">Seleccionar</option>{ordenes.map((order) => <option key={order.idOrden} value={order.idOrden}>{order.codigoOrden}</option>)}</select></label><label>Técnico<select required name="idTecnico"><option value="">Seleccionar</option>{tecnicos.filter(tech=>tech.estado!==false&&tech.disponibilidad!==false).map((tech) => <option key={tech.idTecnico} value={tech.idTecnico}>{tech.nombres} {tech.apellidos}</option>)}</select></label><label>Fecha<input required name="fechaProgramada" type="date" /></label><label>Hora<input required name="horaProgramada" type="time" /></label><button className="primary" type="submit">Guardar asignación</button></form></Modal>}{showEvidence && <Modal title="Registrar evidencia de instalación" onClose={() => setShowEvidence(false)}><form className="form-grid two" onSubmit={createEvidence}><label>Orden<select required name="idOrden"><option value="">Seleccionar</option>{ordenes.map((order) => <option key={order.idOrden} value={order.idOrden}>{order.codigoOrden}</option>)}</select></label><label className="full">Archivo<input required name="archivo" type="file" accept="image/jpeg,image/png,application/pdf" /></label><label className="full">Descripción<textarea required name="descripcion" rows={3} /></label><button className="primary" type="submit">Subir evidencia</button></form><p className="form-help">Se aceptan archivos JPG, PNG o PDF de hasta 10 MB. El archivo se adjuntará a la evidencia de la orden.</p></Modal>}{showProfile && <ProfileModal profileKind={profileKind} setProfileKind={setProfileKind} onSubmit={createProfile} onClose={() => setShowProfile(false)} />}</main>
}

function Welcome({ onLogin, onTrack }: { onLogin: () => void; onTrack: () => void }) { return <div className="welcome"><div className="hero-panel"><span className="eyebrow">SISTEMA INTEGRADO DE FIBERPERU</span><h1>Gestión y seguimiento de instalaciones de red</h1><p>Centraliza solicitudes, órdenes de trabajo, programación de técnicos, dispositivos y evidencias de cada instalación.</p><div className="hero-actions"><button className="primary" onClick={onLogin}>Iniciar sesión</button><button className="secondary" onClick={onTrack}>Consultar una orden</button></div></div><div className="welcome-cards"><article><b>Coordinación</b><span>Evalúa solicitudes y programa órdenes.</span></article><article><b>Técnicos</b><span>Registran instalación, evidencias y observaciones.</span></article><article><b>Clientes</b><span>Solicitan y consultan el avance de su servicio.</span></article></div></div> }
function Dashboard({ solicitudes, ordenes, dispositivos, loading, canSchedule, onNewOrder }: { solicitudes: Solicitud[]; ordenes: Orden[]; dispositivos: Dispositivo[]; loading: boolean; canSchedule: boolean; onNewOrder: () => void }) { const open = ordenes.filter((item) => !['CERRADA','COMPLETADA','FINALIZADA'].some((s) => item.estado?.toUpperCase().includes(s))); const closed = ordenes.length - open.length; const states = Object.entries(ordenes.reduce<Record<string, number>>((a, o) => { const key = o.estado || 'Sin estado'; a[key] = (a[key] || 0) + 1; return a }, {})); return <><div className="page-title"><div><h1>Dashboard</h1><p>Resumen general de solicitudes, órdenes e instalaciones.</p></div>{canSchedule && <button className="primary" onClick={onNewOrder}>+ Nueva programación</button>}</div>{loading ? <Loading /> : <><div className="metrics"><Metric value={solicitudes.length} label="Solicitudes" tone="blue" /><Metric value={open.length} label="Órdenes en proceso" tone="orange" /><Metric value={closed} label="Órdenes cerradas" tone="green" /><Metric value={dispositivos.filter((x) => x.disponibilidad === true).length} label="Equipos disponibles" tone="red" /></div><div className="dashboard-grid"><section className="panel"><h2>Órdenes por estado</h2><div className="state-bars">{states.slice(0,5).map(([state,count]) => <div key={state}><span>{state}</span><strong>{count}</strong><i style={{ width: `${ordenes.length ? count / ordenes.length * 100 : 0}%` }} /></div>)}{!states.length && <Empty text="Aún no hay órdenes registradas." />}</div></section><section className="panel"><h2>Órdenes recientes</h2><Table headers={['Código','Solicitud','Estado']}><tbody>{ordenes.slice(0,5).map((order) => <tr key={order.idOrden}><td><b>{order.codigoOrden}</b></td><td>{order.codigoSolicitud || '—'}</td><td><Status value={order.estado} /></td></tr>)}{!ordenes.length && <EmptyRow columns={3} text="Sin órdenes disponibles." />}</tbody></Table></section></div></>}</> }
function ClienteDashboard({ solicitudes, loading, onCreate, onRequests, onTrack }: { solicitudes: Solicitud[]; loading: boolean; onCreate: () => void; onRequests: () => void; onTrack: () => void }) { const pending=solicitudes.filter(item=>['REGISTRADA','EN_EVALUACION'].includes(item.estado||'')).length; const approved=solicitudes.filter(item=>item.estado==='APROBADA').length; const rejected=solicitudes.filter(item=>['RECHAZADA','CANCELADA'].includes(item.estado||'')).length; return <><div className="client-hero"><div><span className="eyebrow">PORTAL DEL CLIENTE</span><h1>Mis instalaciones</h1><p>Registra solicitudes y consulta el avance de tus servicios contratados.</p></div><div className="action-row"><button className="secondary" onClick={onTrack}>Consultar seguimiento</button><button className="primary" onClick={onCreate}>+ Nueva solicitud</button></div></div>{loading?<Loading/>:<><div className="metrics"><Metric value={solicitudes.length} label="Mis solicitudes" tone="blue"/><Metric value={pending} label="En evaluación" tone="orange"/><Metric value={approved} label="Aprobadas" tone="green"/><Metric value={rejected} label="Rechazadas o canceladas" tone="red"/></div><section className="panel"><div className="panel-heading"><div><h2>Solicitudes recientes</h2><p>Últimos servicios solicitados y su estado actual.</p></div><button className="secondary mini" onClick={onRequests}>Ver todas</button></div><Table headers={['Código','Servicio','Fecha','Estado']}><tbody>{solicitudes.slice(0,5).map(item=><tr key={item.idSolicitud}><td><b>{item.codigoSolicitud}</b></td><td>{item.tipoServicio||'Instalación'}</td><td>{friendlyDate(item.fechaSolicitud)}</td><td><Status value={item.estado}/></td></tr>)}{!solicitudes.length&&<EmptyRow columns={4} text="Aún no tienes solicitudes. Puedes registrar una desde este panel."/>}</tbody></Table></section></>}</> }
function Metric({ value, label, tone }: { value: number; label: string; tone: string }) { return <article className={`metric ${tone}`}><b>{value}</b><span>{label}</span><i /></article> }
function Solicitudes({ solicitudes, ordenes, coordinadores, canCreate, canEvaluate, isAdmin, onCreate, onUpdated }: { solicitudes: Solicitud[]; ordenes: Orden[]; coordinadores: Coordinador[]; canCreate: boolean; canEvaluate: boolean; isAdmin: boolean; onCreate: () => void; onUpdated: () => Promise<void> | void }) {
  const [evaluate,setEvaluate]=useState<Solicitud|null>(null); const [createOrder,setCreateOrder]=useState<Solicitud|null>(null); const [message,setMessage]=useState('')
  const evaluateRequest=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!evaluate)return;const f=new FormData(event.currentTarget);try{await fetchApi('/solicitudes/'+evaluate.idSolicitud+'/evaluar',{method:'PATCH',body:JSON.stringify({resultado:f.get('resultado'),observacion:f.get('observacion')})});setEvaluate(null);setMessage('Solicitud evaluada correctamente.');await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible evaluar la solicitud.')}}
  const createWorkOrder=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!createOrder)return;const f=new FormData(event.currentTarget);try{await fetchApi('/ordenes',{method:'POST',body:JSON.stringify({idSolicitud:createOrder.idSolicitud,idCoordinador:isAdmin?Number(f.get('idCoordinador')):null,codigoOrden:f.get('codigoOrden'),observaciones:f.get('observaciones')})});setCreateOrder(null);setMessage('Orden de trabajo generada.');await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible crear la orden.')}}
  return <><div className="page-title"><div><h1>Solicitudes</h1><p>Registro, evaluación y generación de órdenes de trabajo.</p></div>{canCreate && <button className="primary" onClick={onCreate}>+ Nueva solicitud</button>}</div>{message&&<div className="notice success">{message}</div>}<section className="panel"><Table headers={['Código','Cliente','Servicio','Fecha','Estado','Acciones']}><tbody>{solicitudes.map((x) => {const hasOrder=ordenes.some(order=>order.codigoSolicitud===x.codigoSolicitud);return <tr key={x.idSolicitud}><td><b>{x.codigoSolicitud}</b></td><td>{x.nombreCliente || '—'}</td><td>{x.tipoServicio || 'Instalación'}</td><td>{friendlyDate(x.fechaSolicitud)}</td><td><Status value={x.estado} /></td><td><div className="action-row">{canEvaluate&&!['CANCELADA','APROBADA'].includes(x.estado||'')&&<button className="secondary mini" onClick={()=>setEvaluate(x)}>Evaluar</button>}{canEvaluate&&x.estado==='APROBADA'&&!hasOrder&&<button className="secondary mini" onClick={()=>setCreateOrder(x)}>Generar OT</button>}{hasOrder&&<span className="status info">OT generada</span>}</div></td></tr>})}{!solicitudes.length && <EmptyRow columns={6} text="No se encontraron solicitudes para este usuario." />}</tbody></Table></section>
    {evaluate&&<Modal title={'Evaluar '+evaluate.codigoSolicitud} onClose={()=>setEvaluate(null)}><form className="form-grid" onSubmit={evaluateRequest}><label>Resultado<select name="resultado" required><option value="APROBADA">Aprobar</option><option value="RECHAZADA">Rechazar</option></select></label><label>Observación<textarea name="observacion" rows={3} placeholder="Obligatoria cuando se rechaza"/></label><button className="primary">Guardar evaluación</button></form></Modal>}
    {createOrder&&<Modal title={'Generar orden para '+createOrder.codigoSolicitud} onClose={()=>setCreateOrder(null)}><form className="form-grid" onSubmit={createWorkOrder}>{isAdmin&&<label>Coordinador responsable<select name="idCoordinador" required><option value="">Seleccionar</option>{coordinadores.filter(item=>item.estado!==false).map(item=><option key={item.idCoordinador} value={item.idCoordinador}>{item.nombres} {item.apellidos}</option>)}</select></label>}<label>Código de orden<input name="codigoOrden" required placeholder="OT-2026-0002" maxLength={20}/></label><label>Observaciones<textarea name="observaciones" rows={3}/></label><button className="primary">Generar orden</button></form></Modal>}
  </>
}
function Programacion({ ordenes, tecnicos, allowed, onOpen }: { ordenes: Orden[]; tecnicos: Tecnico[]; allowed: boolean; onOpen: () => void }) { const pending = ordenes.filter((x) => !x.nombreTecnico || !x.fechaProgramada); return <><div className="page-title"><div><h1>Programación y asignación</h1><p>Asigna técnico, fecha y hora a cada orden de trabajo.</p></div>{allowed && <button className="primary" onClick={onOpen}>+ Asignar orden</button>}</div>{!allowed && <div className="notice warning">Tu rol puede consultar órdenes, pero la asignación está restringida en el backend a Coordinador o Administrador.</div>}<div className="dashboard-grid"><section className="panel"><h2>Órdenes pendientes</h2>{pending.map((x) => <div className="assignment" key={x.idOrden}><div><b>{x.codigoOrden}</b><span>{x.codigoSolicitud || 'Sin solicitud asociada'}</span></div><Status value={x.estado} /></div>)}{!pending.length && <Empty text="No hay órdenes pendientes de programación." />}</section><section className="panel"><h2>Disponibilidad de técnicos</h2>{tecnicos.map((x) => <div className="assignment" key={x.idTecnico}><div><b>{x.nombres} {x.apellidos}</b><span>{x.especialidad || 'Técnico instalador'}</span></div><Status value={x.disponibilidad === true ? 'Disponible' : 'No disponible'} /></div>)}{!tecnicos.length && <Empty text="El backend no devolvió técnicos disponibles." />}</section></div></> }
function Evidencias({ evidencias, canCreate, canValidate, onCreate, onUpdated }: { evidencias: Evidencia[]; canCreate: boolean; canValidate: boolean; onCreate: () => void; onUpdated: () => Promise<void> | void }) {
  const [selected,setSelected]=useState<Evidencia|null>(null); const [message,setMessage]=useState('')
  const validate=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!selected)return;const f=new FormData(event.currentTarget);try{await fetchApi('/evidencias/'+selected.idEvidencia+'/validacion',{method:'PATCH',body:JSON.stringify({estadoValidacion:f.get('estadoValidacion'),observacionValidacion:f.get('observacionValidacion')})});setSelected(null);setMessage('Evidencia validada correctamente.');await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible validar la evidencia.')}}
  return <><div className="page-title"><div><h1>Evidencias y observaciones</h1><p>Registro y validación de archivos de instalación.</p></div>{canCreate && <button className="primary" onClick={onCreate}>+ Registrar evidencia</button>}</div>{message&&<div className="notice success">{message}</div>}<section className="panel"><Table headers={['Orden','Archivo','Descripción','Registro','Validación','Acción']}><tbody>{evidencias.map((x) => <tr key={x.idEvidencia}><td><b>{x.codigoOrden || `OT #${x.idOrden}`}</b></td><td>{x.urlArchivo?<a href={x.urlArchivo} target="_blank" rel="noreferrer">{x.nombreArchivo||'Abrir archivo'}</a>:x.nombreArchivo||'—'}</td><td>{x.descripcion || '—'}{x.observacionValidacion&&<><br/><small>{x.observacionValidacion}</small></>}</td><td>{friendlyDate(x.fechaRegistro)}</td><td><Status value={x.estadoValidacion} /></td><td>{canValidate&&x.estadoValidacion==='PENDIENTE'&&<button className="secondary mini" onClick={()=>setSelected(x)}>Revisar</button>}</td></tr>)}{!evidencias.length && <EmptyRow columns={6} text="No hay evidencias visibles para este rol." />}</tbody></Table></section>{selected&&<Modal title={'Validar evidencia de '+(selected.codigoOrden||selected.idOrden)} onClose={()=>setSelected(null)}><form className="form-grid" onSubmit={validate}><label>Resultado<select name="estadoValidacion" required><option value="APROBADA">Aprobar</option><option value="OBSERVADA">Observar y devolver</option><option value="RECHAZADA">Rechazar</option></select></label><label>Observación<textarea name="observacionValidacion" rows={3} placeholder="Obligatoria para observar o rechazar"/></label><button className="primary">Guardar validación</button></form></Modal>}</>
}
function Seguimiento({ tracking, onSubmit }: { tracking: SeguimientoResultado | null; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <><div className="page-title"><div><h1>Seguimiento de instalación</h1><p>Consulta el avance usando el código de solicitud SOL o el código de orden OT.</p></div></div><section className="track-panel"><form onSubmit={onSubmit}><label>Código de solicitud u orden<input required name="codigo" placeholder="SOL-2026-0001 u OT-2026-0001" /></label><button className="primary" type="submit">Consultar</button></form>{tracking && <div className="tracking-result"><div><span>Código consultado</span><h2>{tracking.codigoConsultado}</h2><p>{tracking.etapaActual}</p></div><Status value={tracking.estadoActual} /><dl><div><dt>Solicitud</dt><dd>{tracking.codigoSolicitud}</dd><small><Status value={tracking.estadoSolicitud}/></small></div><div><dt>Orden de trabajo</dt><dd>{tracking.codigoOrden || 'Pendiente de generación'}</dd>{tracking.estadoOrden&&<small><Status value={tracking.estadoOrden}/></small>}</div><div><dt>Servicio</dt><dd>{tracking.tipoServicio||'—'}</dd></div><div><dt>Técnico</dt><dd>{tracking.nombreTecnico || 'Por asignar'}</dd></div><div><dt>Programación</dt><dd>{tracking.fechaProgramada ? `${friendlyDate(tracking.fechaProgramada)} · ${tracking.horaProgramada || ''}` : 'Sin programación'}</dd></div></dl></div>}</section></> }
function ProfileModal({ profileKind, setProfileKind, onSubmit, onClose }: { profileKind: ProfileKind; setProfileKind: (value: ProfileKind) => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onClose: () => void }) {
  return <Modal title="Registrar persona y acceso" onClose={onClose}><form className="form-grid two" onSubmit={onSubmit}>
    <label>Tipo de perfil<select value={profileKind} onChange={(event) => setProfileKind(event.target.value as ProfileKind)}><option value="CLIENTE">Cliente</option><option value="TECNICO">Técnico</option><option value="COORDINADOR">Coordinador</option></select></label><span />
    <label>Nombres<input required name="nombres" /></label><label>Apellidos<input required name="apellidos" /></label>
    <label>Correo<input required name="correo" type="email" /></label><label>Teléfono<input name="telefono" /></label>
    <label className="full">Contraseña temporal<input required name="password" type="password" minLength={8} /></label>
    {profileKind === 'CLIENTE' && <><label>Tipo de documento<select name="tipoDocumento"><option>DNI</option><option>RUC</option><option>CE</option></select></label><label>Número de documento<input required name="numeroDocumento" /></label><label>Razón social<input name="razonSocial" /></label><label>Dirección<input required name="direccion" /></label></>}
    {profileKind === 'TECNICO' && <label className="full">Especialidad<input name="especialidad" /></label>}
    {profileKind === 'COORDINADOR' && <label className="full">Cargo<input required name="cargo" /></label>}
    <button className="primary" type="submit">Registrar persona</button>
  </form></Modal>
}
function OrdenesAvanzadas({ ordenes, solicitudes, dispositivos, canSchedule, canOperate, isTecnico, onSchedule, onUpdated }: { ordenes: Orden[]; solicitudes: Solicitud[]; dispositivos: Dispositivo[]; canSchedule: boolean; canOperate: boolean; isTecnico: boolean; onSchedule: () => void; onUpdated: () => Promise<void> | void }) {
  const [search, setSearch] = useState(''); const [state, setState] = useState(''); const [from, setFrom] = useState(''); const [to, setTo] = useState('')
  const [detail,setDetail]=useState<Orden|null>(null); const [assigned,setAssigned]=useState<OrdenDispositivo[]>([]); const [observations,setObservations]=useState<Observacion[]>([]); const [message,setMessage]=useState('')
  const clientByRequest = new Map(solicitudes.map((item) => [item.codigoSolicitud, item.nombreCliente || '']))
  const filtered = ordenes.filter((item) => {
    const text = [item.codigoOrden, item.codigoSolicitud, item.nombreTecnico, clientByRequest.get(item.codigoSolicitud || '')].join(' ').toLowerCase()
    return text.includes(search.toLowerCase()) && (!state || item.estado === state) && (!from || (item.fechaProgramada || '') >= from) && (!to || (item.fechaProgramada || '') <= to)
  })
  const exportCsv = () => {
    const summary=Object.entries(filtered.reduce<Record<string,number>>((acc,item)=>{const key=item.estado||'SIN_ESTADO';acc[key]=(acc[key]||0)+1;return acc},{}))
    const rows = [['REPORTE CONSOLIDADO DE ÓRDENES'],['Estado','Cantidad'],...summary,[""],["Código","Solicitud","Cliente","Técnico","Fecha","Estado"], ...filtered.map((item) => [item.codigoOrden,item.codigoSolicitud || '',clientByRequest.get(item.codigoSolicitud || '') || '',item.nombreTecnico || '',item.fechaProgramada || '',item.estado || ''])]
    const blob = new Blob(['\uFEFF'+rows.map((row) => row.map((value) => '"' + String(value).replaceAll('"','""') + '"').join(',')).join('\n')], { type: 'text/csv;charset=utf-8' })
    const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'reporte-ordenes-fiberperu.csv'; link.click(); URL.revokeObjectURL(link.href)
  }
  const states = [...new Set(ordenes.map((item) => item.estado).filter(Boolean))]
  const pendingCount=filtered.filter(item=>['REGISTRADA','PROGRAMADA','ASIGNADA'].includes(item.estado||'')).length; const runningCount=filtered.filter(item=>['EN_PROCESO','OBSERVADA'].includes(item.estado||'')).length; const closedCount=filtered.filter(item=>item.estado==='FINALIZADA').length
  const openDetail=async(item:Orden)=>{setMessage('');try{const [devices,notes]=await Promise.all([fetchApi<OrdenDispositivo[]>('/ordenes-dispositivos/orden/'+item.idOrden),fetchApi<Observacion[]>('/observaciones/orden/'+item.idOrden)]);setAssigned(devices);setObservations(notes);setDetail(item)}catch(e){setMessage(e instanceof Error?e.message:'No fue posible cargar el detalle de la orden.')}}
  const changeState=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!detail)return;const f=new FormData(event.currentTarget);try{const updated=await fetchApi<Orden>('/ordenes/'+detail.idOrden+'/estado',{method:'PATCH',body:JSON.stringify({estadoNuevo:f.get('estadoNuevo'),motivo:f.get('motivo')})});setDetail(updated);setMessage('Estado de la orden actualizado.');await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible actualizar el estado.')}}
  const assignDevice=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!detail)return;const f=new FormData(event.currentTarget);try{await fetchApi('/ordenes-dispositivos',{method:'POST',body:JSON.stringify({idOrden:detail.idOrden,idDispositivo:Number(f.get('idDispositivo')),observaciones:f.get('observaciones')})});setMessage('Dispositivo vinculado a la orden.');await openDetail(detail);await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible vincular el dispositivo.')}}
  const installDevice=async(item:OrdenDispositivo)=>{try{await fetchApi('/ordenes-dispositivos/'+item.idOrdenDispositivo+'/instalar',{method:'PATCH'});if(detail)await openDetail(detail);await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible marcar el dispositivo como instalado.')}}
  const addObservation=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!detail?.idTecnico)return;const f=new FormData(event.currentTarget);try{await fetchApi('/observaciones',{method:'POST',body:JSON.stringify({idOrden:detail.idOrden,idTecnico:detail.idTecnico,descripcion:f.get('descripcion')})});(event.currentTarget as HTMLFormElement).reset();setMessage('Observación registrada.');await openDetail(detail)}catch(e){setMessage(e instanceof Error?e.message:'No fue posible registrar la observación.')}}
  const availableDevices=dispositivos.filter(device=>device.disponibilidad===true&&device.estado==='EN_STOCK')
  return <><div className="page-title"><div><h1>Órdenes de trabajo</h1><p>Consulta, detalle operativo, filtros y reporte exportable.</p></div><div className="action-row"><button className="secondary" onClick={exportCsv}>Exportar CSV</button>{canSchedule && <button className="primary" onClick={onSchedule}>Programar orden</button>}</div></div>{message&&<div className="notice warning">{message}</div>}
    <div className="metrics compact-metrics"><Metric value={filtered.length} label="Órdenes del reporte" tone="blue"/><Metric value={pendingCount} label="Pendientes o programadas" tone="orange"/><Metric value={runningCount} label="En ejecución u observadas" tone="red"/><Metric value={closedCount} label="Finalizadas" tone="green"/></div><section className="panel filter-grid"><label>Cliente, técnico o código<input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar..." /></label><label>Estado<select value={state} onChange={(e) => setState(e.target.value)}><option value="">Todos</option>{states.map((value) => <option key={value} value={value}>{value}</option>)}</select></label><label>Desde<input type="date" value={from} onChange={(e) => setFrom(e.target.value)} /></label><label>Hasta<input type="date" value={to} onChange={(e) => setTo(e.target.value)} /></label></section>
    <section className="panel"><Table headers={['Código','Solicitud / cliente','Técnico','Programación','Estado','Acción']}><tbody>{filtered.map((item) => <tr key={item.idOrden}><td><b>{item.codigoOrden}</b></td><td>{item.codigoSolicitud || '—'}<br />{clientByRequest.get(item.codigoSolicitud || '')}</td><td>{item.nombreTecnico || 'Sin asignar'}</td><td>{item.fechaProgramada ? friendlyDate(item.fechaProgramada) + ' · ' + (item.horaProgramada || '') : 'Sin programar'}</td><td><Status value={item.estado} /></td><td><button className="secondary mini" onClick={()=>void openDetail(item)}>Ver detalle</button></td></tr>)}{!filtered.length && <EmptyRow columns={6} text="No hay órdenes que coincidan con los filtros." />}</tbody></Table></section>
    {detail&&<Modal title={'Detalle '+detail.codigoOrden} onClose={()=>setDetail(null)}><div className="detail-summary"><div><span>Solicitud</span><b>{detail.codigoSolicitud||'—'}</b></div><div><span>Técnico</span><b>{detail.nombreTecnico||'Sin asignar'}</b></div><div><span>Programación</span><b>{detail.fechaProgramada?friendlyDate(detail.fechaProgramada)+' '+(detail.horaProgramada||''):'Sin programar'}</b></div><div><span>Estado</span><Status value={detail.estado}/></div></div>
      {canOperate&&<form className="form-grid two subsection" onSubmit={changeState}><h3 className="full">Actualizar estado</h3><label>Nuevo estado<select name="estadoNuevo" required defaultValue="EN_PROCESO"><option>REGISTRADA</option><option>PROGRAMADA</option><option>ASIGNADA</option><option>EN_PROCESO</option><option>OBSERVADA</option><option>FINALIZADA</option><option>CANCELADA</option></select></label><label>Motivo<input name="motivo" placeholder="Motivo u observación"/></label><button className="secondary">Actualizar estado</button></form>}
      <section className="subsection"><h3>Equipos vinculados</h3>{assigned.map(item=><div className="assignment" key={item.idOrdenDispositivo}><div><b>{item.numeroSerie}</b><span>{item.tipoDispositivo} · {item.marca} {item.modelo}</span></div><div className="action-row"><Status value={item.estadoAsignacion}/>{item.estadoAsignacion==='ASIGNADO'&&<button className="secondary mini" onClick={()=>void installDevice(item)}>Marcar instalado</button>}</div></div>)}{!assigned.length&&<Empty text="Aún no hay equipos vinculados."/>}</section>
      {canOperate&&<form className="form-grid two subsection" onSubmit={assignDevice}><label>Dispositivo disponible<select name="idDispositivo" required><option value="">Seleccionar por serie</option>{availableDevices.map(item=><option key={item.idDispositivo} value={item.idDispositivo}>{item.numeroSerie} · {item.tipoDispositivo}</option>)}</select></label><label>Observación<input name="observaciones"/></label><button className="secondary">Vincular dispositivo</button></form>}
      <section className="subsection"><h3>Observaciones técnicas</h3>{observations.map(item=><div className="assignment" key={item.idObservacion}><div><b>{item.nombreTecnico||'Técnico'}</b><span>{item.descripcion}</span></div><small>{friendlyDate(item.fechaRegistro)}</small></div>)}{!observations.length&&<Empty text="No hay observaciones registradas."/>}</section>
      {isTecnico&&detail.idTecnico&&<form className="form-grid subsection" onSubmit={addObservation}><label>Nueva observación<textarea name="descripcion" required rows={3} maxLength={500}/></label><button className="secondary">Registrar observación</button></form>}
    </Modal>}
  </>
}
function AdminPersonas({ usuarios, clientes, tecnicos, coordinadores, onCreate, onUpdated }: { usuarios: Usuario[]; clientes: Cliente[]; tecnicos: Tecnico[]; coordinadores: Coordinador[]; onCreate: () => void; onUpdated: () => Promise<void> | void }) {
  const [editUser, setEditUser] = useState<Usuario | null>(null); const [editClient, setEditClient] = useState<Cliente | null>(null); const [editTech, setEditTech] = useState<Tecnico | null>(null); const [message, setMessage] = useState('')
  const [userSearch, setUserSearch] = useState(''); const [roleFilter, setRoleFilter] = useState(''); const [userState, setUserState] = useState('')
  const normalizedSearch = userSearch.trim().toLowerCase()
  const filteredUsers = usuarios.filter((item) => {
    const matchesText = [item.nombres, item.apellidos, item.correo].join(' ').toLowerCase().includes(normalizedSearch)
    const matchesRole = !roleFilter || item.rol === roleFilter
    const matchesState = !userState || String(Boolean(item.estado)) === userState
    return matchesText && matchesRole && matchesState
  })
  const roles = [...new Set(usuarios.map((item) => item.rol))]
  const toggle = async (path: string, active: boolean) => { try { await fetchApi(path + '?activo=' + active, { method:'PATCH' }); setMessage('Estado actualizado.'); await onUpdated() } catch(e) { setMessage(e instanceof Error ? e.message : 'No fue posible actualizar el estado.') } }
  const toggleAvailability = async (item: Tecnico) => { try { await fetchApi('/tecnicos/'+item.idTecnico+'/disponibilidad?disponible='+(!item.disponibilidad), { method:'PATCH' }); setMessage('Disponibilidad del técnico actualizada.'); await onUpdated() } catch(e) { setMessage(e instanceof Error ? e.message : 'No fue posible actualizar la disponibilidad.') } }
  const updateUser = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if(!editUser)return; const f=new FormData(event.currentTarget); try { await fetchApi('/usuarios/'+editUser.idUsuario,{method:'PUT',body:JSON.stringify({nombres:f.get('nombres'),apellidos:f.get('apellidos'),correo:f.get('correo'),telefono:f.get('telefono')})}); setEditUser(null); setMessage('Usuario actualizado.'); await onUpdated() } catch(e){setMessage(e instanceof Error?e.message:'No fue posible actualizar.')} }
  const updateClient = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if(!editClient)return; const f=new FormData(event.currentTarget); try { await fetchApi('/clientes/'+editClient.idCliente,{method:'PUT',body:JSON.stringify(Object.fromEntries(f))}); setEditClient(null); setMessage('Cliente actualizado.'); await onUpdated() } catch(e){setMessage(e instanceof Error?e.message:'No fue posible actualizar.')} }
  const updateTech = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if(!editTech)return; const f=new FormData(event.currentTarget); try { await fetchApi('/tecnicos/'+editTech.idTecnico+'/especialidad',{method:'PATCH',body:JSON.stringify({especialidad:f.get('especialidad')})}); setEditTech(null); setMessage('Especialidad del técnico actualizada.'); await onUpdated() } catch(e){setMessage(e instanceof Error?e.message:'No fue posible actualizar al técnico.')} }
  return <><div className="page-title"><div><h1>Personas y accesos</h1><p>Registro, actualización y estado de cuentas y perfiles.</p></div><button className="primary" onClick={onCreate}>+ Registrar persona</button></div>{message && <div className="notice success">{message}</div>}
    <section className="panel filter-grid person-filters"><label>Buscar usuario<input value={userSearch} onChange={(event)=>setUserSearch(event.target.value)} placeholder="Nombre, apellido o correo" /></label><label>Rol<select value={roleFilter} onChange={(event)=>setRoleFilter(event.target.value)}><option value="">Todos los roles</option>{roles.map((role)=><option key={role} value={role}>{role.replace('ROLE_','')}</option>)}</select></label><label>Estado<select value={userState} onChange={(event)=>setUserState(event.target.value)}><option value="">Todos</option><option value="true">Activos</option><option value="false">Inactivos</option></select></label><div className="result-count"><b>{filteredUsers.length}</b><span>usuarios encontrados</span></div></section>
    <section className="panel"><h2>Usuarios</h2><Table headers={['Nombre','Rol','Correo','Estado','Acciones']}><tbody>{filteredUsers.map((item)=><tr key={item.idUsuario}><td><b>{item.nombres} {item.apellidos}</b></td><td>{item.rol.replace('ROLE_','')}</td><td>{item.correo}</td><td><Status value={item.estado?'Activo':'Inactivo'} /></td><td><div className="action-row"><button className="secondary mini" onClick={()=>setEditUser(item)}>Editar</button><button className="secondary mini" onClick={()=>toggle('/usuarios/'+item.idUsuario+'/estado',!item.estado)}>{item.estado?'Desactivar':'Activar'}</button></div></td></tr>)}{!filteredUsers.length&&<EmptyRow columns={5} text="No hay usuarios que coincidan con los filtros." />}</tbody></Table></section>
    <section className="panel spaced"><h2>Clientes</h2><Table headers={['Nombre','Documento','Estado','Acciones']}><tbody>{clientes.map((item)=><tr key={item.idCliente}><td><b>{item.nombres} {item.apellidos}</b><br />{item.correo}</td><td>{item.tipoDocumento} {item.numeroDocumento}</td><td><Status value={item.estado?'Activo':'Inactivo'} /></td><td><div className="action-row"><button className="secondary mini" onClick={()=>setEditClient(item)}>Editar perfil</button><button className="secondary mini" onClick={()=>toggle('/clientes/'+item.idCliente+'/estado',!item.estado)}>{item.estado?'Desactivar':'Activar'}</button></div></td></tr>)}</tbody></Table></section>
    <div className="dashboard-grid spaced"><section className="panel"><h2>Técnicos</h2>{tecnicos.map(item=><div className="assignment management-row" key={item.idTecnico}><div><b>{item.nombres} {item.apellidos}</b><span>{item.especialidad||'Sin especialidad'} · {item.estado?'Activo':'Inactivo'}</span></div><div className="action-row"><Status value={item.disponibilidad}/><button className="secondary mini" onClick={()=>setEditTech(item)}>Especialidad</button><button className="secondary mini" onClick={()=>toggleAvailability(item)}>{item.disponibilidad?'No disponible':'Disponible'}</button><button className="secondary mini" onClick={()=>toggle('/tecnicos/'+item.idTecnico+'/estado',!item.estado)}>{item.estado?'Desactivar':'Activar'}</button></div></div>)}{!tecnicos.length&&<Empty text="No hay técnicos registrados." />}</section><section className="panel"><h2>Coordinadores</h2>{coordinadores.map(item=><div className="assignment" key={item.idCoordinador}><div><b>{item.nombres} {item.apellidos}</b><span>{item.cargo}</span></div><Status value={item.estado?'Activo':'Inactivo'}/></div>)}</section></div>
    {editUser && <Modal title="Actualizar usuario" onClose={()=>setEditUser(null)}><form className="form-grid two" onSubmit={updateUser}><label>Nombres<input name="nombres" required defaultValue={editUser.nombres}/></label><label>Apellidos<input name="apellidos" required defaultValue={editUser.apellidos}/></label><label>Correo<input name="correo" type="email" required defaultValue={editUser.correo}/></label><label>Teléfono<input name="telefono"/></label><button className="primary">Guardar cambios</button></form></Modal>}
    {editClient && <Modal title="Actualizar cliente" onClose={()=>setEditClient(null)}><form className="form-grid two" onSubmit={updateClient}><label>Nombres<input name="nombres" required defaultValue={editClient.nombres}/></label><label>Apellidos<input name="apellidos" required defaultValue={editClient.apellidos}/></label><label>Correo<input name="correo" type="email" required defaultValue={editClient.correo}/></label><label>Teléfono<input name="telefono" defaultValue={editClient.telefono}/></label><label>Tipo de documento<select name="tipoDocumento" defaultValue={editClient.tipoDocumento}><option>DNI</option><option>RUC</option><option>CE</option><option>PASAPORTE</option></select></label><label>Número<input name="numeroDocumento" required defaultValue={editClient.numeroDocumento}/></label><label>Razón social<input name="razonSocial" defaultValue={editClient.razonSocial}/></label><label>Dirección<input name="direccion" required defaultValue={editClient.direccion}/></label><button className="primary">Guardar cambios</button></form></Modal>}
    {editTech && <Modal title="Actualizar especialidad del técnico" onClose={()=>setEditTech(null)}><form className="form-grid" onSubmit={updateTech}><p className="form-help">{editTech.nombres} {editTech.apellidos}</p><label>Especialidad<input name="especialidad" required defaultValue={editTech.especialidad}/></label><button className="primary">Guardar especialidad</button></form></Modal>}
  </>
}
function AdminInventario({ dispositivos, tipos, admin, onUpdated }: { dispositivos: Dispositivo[]; tipos: TipoDispositivo[]; admin: boolean; onUpdated: () => Promise<void> | void }) {
  const [mode,setMode]=useState<'device'|'type'|null>(null); const [message,setMessage]=useState(''); const [tab,setTab]=useState<'devices'|'types'>('devices')
  const [search,setSearch]=useState(''); const [typeFilter,setTypeFilter]=useState(''); const [stateFilter,setStateFilter]=useState(''); const [availabilityFilter,setAvailabilityFilter]=useState('')
  const [editType,setEditType]=useState<TipoDispositivo|null>(null); const [editDevice,setEditDevice]=useState<Dispositivo|null>(null)
  const submit=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const f=new FormData(event.currentTarget);try{await fetchApi(mode==='type'?'/tipos-dispositivo':'/dispositivos',{method:'POST',body:JSON.stringify(mode==='type'?{nombre:f.get('nombre'),descripcion:f.get('descripcion')}:{idTipoDispositivo:Number(f.get('idTipoDispositivo')),marca:f.get('marca'),modelo:f.get('modelo'),numeroSerie:f.get('numeroSerie')})});setMode(null);setMessage('Registro creado correctamente.');await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible registrar.')}}
  const toggle=async(id:number,current:boolean)=>{try{await fetchApi('/dispositivos/'+id+'/disponibilidad?disponible='+(!current),{method:'PATCH'});await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible cambiar la disponibilidad.')}}
  const updateType=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!editType)return;const f=new FormData(event.currentTarget);try{await fetchApi('/tipos-dispositivo/'+editType.idTipoDispositivo,{method:'PUT',body:JSON.stringify({nombre:f.get('nombre'),descripcion:f.get('descripcion')})});setEditType(null);setMessage('Tipo de dispositivo actualizado.');await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible actualizar el tipo.')}}
  const toggleType=async(item:TipoDispositivo)=>{try{await fetchApi('/tipos-dispositivo/'+item.idTipoDispositivo+'/estado?activo='+(!item.estado),{method:'PATCH'});setMessage('Estado del tipo actualizado.');await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible cambiar el estado del tipo.')}}
  const updateDevice=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!editDevice)return;const f=new FormData(event.currentTarget);try{await fetchApi('/dispositivos/'+editDevice.idDispositivo,{method:'PUT',body:JSON.stringify({idTipoDispositivo:Number(f.get('idTipoDispositivo')),marca:f.get('marca'),modelo:f.get('modelo'),numeroSerie:f.get('numeroSerie')})});await fetchApi('/dispositivos/'+editDevice.idDispositivo+'/estado?estado='+encodeURIComponent(String(f.get('estado'))),{method:'PATCH'});setEditDevice(null);setMessage('Dispositivo actualizado.');await onUpdated()}catch(e){setMessage(e instanceof Error?e.message:'No fue posible actualizar el dispositivo.')}}
  const filtered=dispositivos.filter(item=>{const text=[item.numeroSerie,item.marca,item.modelo,item.tipoDispositivo].join(' ').toLowerCase();return text.includes(search.toLowerCase())&&(!typeFilter||String(item.idTipoDispositivo)===typeFilter)&&(!stateFilter||item.estado===stateFilter)&&(!availabilityFilter||String(Boolean(item.disponibilidad))===availabilityFilter)})
  const states=[...new Set(dispositivos.map(item=>item.estado).filter((value):value is string=>Boolean(value)))]
  const stock=dispositivos.filter(item=>item.estado==='EN_STOCK').length; const assigned=dispositivos.filter(item=>['ASIGNADO','INSTALADO'].includes(item.estado||'')).length; const unavailable=dispositivos.filter(item=>!item.disponibilidad).length
  return <><div className="page-title"><div><h1>Equipos e inventario</h1><p>Catálogo de tipos y control de unidades físicas por número de serie.</p></div>{admin&&<div className="action-row"><button className="secondary" onClick={()=>{setTab('types');setMode('type')}}>+ Tipo</button><button className="primary" onClick={()=>{setTab('devices');setMode('device')}}>+ Dispositivo</button></div>}</div>{message&&<div className="notice success">{message}</div>}
    <div className="metrics compact-metrics"><Metric value={dispositivos.length} label="Unidades registradas" tone="blue"/><Metric value={stock} label="En stock" tone="green"/><Metric value={assigned} label="Asignadas o instaladas" tone="orange"/><Metric value={unavailable} label="No disponibles" tone="red"/></div>
    <div className="tabs" role="tablist"><button className={tab==='devices'?'active':''} onClick={()=>setTab('devices')}>Dispositivos físicos</button><button className={tab==='types'?'active':''} onClick={()=>setTab('types')}>Tipos de dispositivo</button></div>
    {tab==='devices'&&<><section className="panel filter-grid inventory-filters"><label>Buscar<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Serie, marca, modelo o tipo"/></label><label>Tipo<select value={typeFilter} onChange={e=>setTypeFilter(e.target.value)}><option value="">Todos</option>{tipos.map(item=><option key={item.idTipoDispositivo} value={item.idTipoDispositivo}>{item.nombre}</option>)}</select></label><label>Estado<select value={stateFilter} onChange={e=>setStateFilter(e.target.value)}><option value="">Todos</option>{states.map(value=><option key={value}>{value}</option>)}</select></label><label>Disponibilidad<select value={availabilityFilter} onChange={e=>setAvailabilityFilter(e.target.value)}><option value="">Todas</option><option value="true">Disponible</option><option value="false">No disponible</option></select></label></section>
    <section className="panel"><Table headers={['Serie','Tipo','Marca / modelo','Estado','Disponibilidad','Acciones']}><tbody>{filtered.map(item=><tr key={item.idDispositivo}><td><b>{item.numeroSerie}</b></td><td>{item.tipoDispositivo}</td><td>{item.marca} {item.modelo}</td><td><Status value={item.estado}/></td><td><Status value={item.disponibilidad}/></td><td>{admin&&<div className="action-row"><button className="secondary mini" onClick={()=>setEditDevice(item)}>Editar</button><button className="secondary mini" onClick={()=>toggle(item.idDispositivo,Boolean(item.disponibilidad))}>{item.disponibilidad?'No disponible':'Disponible'}</button></div>}</td></tr>)}{!filtered.length&&<EmptyRow columns={6} text="No hay dispositivos que coincidan con los filtros."/>}</tbody></Table></section></>}
    {tab==='types'&&<section className="panel"><h2>Tipos de dispositivo</h2><p className="section-help">Un tipo es una categoría reutilizable; cada dispositivo físico conserva su propia marca, modelo y serie.</p><Table headers={['Tipo','Descripción','Estado','Dispositivos','Acciones']}><tbody>{tipos.map(item=><tr key={item.idTipoDispositivo}><td><b>{item.nombre}</b></td><td>{item.descripcion||'—'}</td><td><Status value={item.estado?'Activo':'Inactivo'}/></td><td>{dispositivos.filter(device=>device.idTipoDispositivo===item.idTipoDispositivo).length}</td><td>{admin&&<div className="action-row"><button className="secondary mini" onClick={()=>setEditType(item)}>Editar</button><button className="secondary mini" onClick={()=>toggleType(item)}>{item.estado?'Desactivar':'Activar'}</button></div>}</td></tr>)}{!tipos.length&&<EmptyRow columns={5} text="No hay tipos registrados."/>}</tbody></Table></section>}
    {mode&&<Modal title={mode==='type'?'Registrar tipo':'Registrar dispositivo'} onClose={()=>setMode(null)}><form className="form-grid two" onSubmit={submit}>{mode==='type'?<><label>Nombre<input name="nombre" required/></label><label>Descripción<input name="descripcion"/></label></>:<><label>Tipo<select name="idTipoDispositivo">{tipos.filter(t=>t.estado!==false).map(t=><option key={t.idTipoDispositivo} value={t.idTipoDispositivo}>{t.nombre}</option>)}</select></label><label>Marca<input name="marca" required/></label><label>Modelo<input name="modelo" required/></label><label>Número de serie<input name="numeroSerie" required/></label></>}<button className="primary">Registrar</button></form></Modal>}
    {editType&&<Modal title="Actualizar tipo de dispositivo" onClose={()=>setEditType(null)}><form className="form-grid" onSubmit={updateType}><label>Nombre<input name="nombre" required defaultValue={editType.nombre}/></label><label>Descripción<textarea name="descripcion" defaultValue={editType.descripcion}/></label><button className="primary">Guardar cambios</button></form></Modal>}
    {editDevice&&<Modal title="Actualizar dispositivo" onClose={()=>setEditDevice(null)}><form className="form-grid two" onSubmit={updateDevice}><label>Tipo<select name="idTipoDispositivo" defaultValue={editDevice.idTipoDispositivo}>{tipos.filter(t=>t.estado!==false||t.idTipoDispositivo===editDevice.idTipoDispositivo).map(t=><option key={t.idTipoDispositivo} value={t.idTipoDispositivo}>{t.nombre}</option>)}</select></label><label>Estado<select name="estado" defaultValue={editDevice.estado}><option>EN_STOCK</option><option>ASIGNADO</option><option>INSTALADO</option><option>RETIRADO</option><option>DEFECTUOSO</option><option>INACTIVO</option></select></label><label>Marca<input name="marca" required defaultValue={editDevice.marca}/></label><label>Modelo<input name="modelo" required defaultValue={editDevice.modelo}/></label><label className="full">Número de serie<input name="numeroSerie" required defaultValue={editDevice.numeroSerie}/></label><button className="primary">Guardar cambios</button></form></Modal>}
  </>
}
function HistorialView({ historial, solicitudes, ordenes }: { historial: Historial[]; solicitudes: Solicitud[]; ordenes: Orden[] }) {
  const [search,setSearch]=useState(''); const [tab,setTab]=useState<'lifecycle'|'events'>('lifecycle'); const rows=historial.filter(item=>[item.codigoOrden,item.nombreUsuario,item.tipoEvento,item.estadoNuevo].join(' ').toLowerCase().includes(search.toLowerCase()))
  const lifecycle=solicitudes.filter(item=>[item.codigoSolicitud,item.nombreCliente,item.estado].join(' ').toLowerCase().includes(search.toLowerCase())).map(item=>({request:item,order:ordenes.find(order=>order.codigoSolicitud===item.codigoSolicitud)}))
  return <><div className="page-title"><div><h1>Historial y trazabilidad</h1><p>Ciclo completo desde la solicitud hasta el cierre de la instalación.</p></div></div><section className="panel filter-grid"><label>Buscar<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Solicitud, orden, cliente, usuario o evento"/></label></section><div className="tabs"><button className={tab==='lifecycle'?'active':''} onClick={()=>setTab('lifecycle')}>Ciclo de solicitudes</button><button className={tab==='events'?'active':''} onClick={()=>setTab('events')}>Auditoría de órdenes</button></div>{tab==='lifecycle'?<section className="panel"><Table headers={['Solicitud','Cliente','Estado solicitud','Orden','Técnico','Programación','Estado final']}><tbody>{lifecycle.map(({request,order})=><tr key={request.idSolicitud}><td><b>{request.codigoSolicitud}</b><br/><small>{friendlyDate(request.fechaSolicitud)}</small></td><td>{request.nombreCliente||'—'}</td><td><Status value={request.estado}/></td><td>{order?.codigoOrden||'Sin generar'}</td><td>{order?.nombreTecnico||'Sin asignar'}</td><td>{order?.fechaProgramada?friendlyDate(order.fechaProgramada)+' '+(order.horaProgramada||''):'Sin programar'}</td><td><Status value={order?.estado||'PENDIENTE'}/></td></tr>)}{!lifecycle.length&&<EmptyRow columns={7} text="No se encontraron ciclos operativos."/>}</tbody></Table></section>:<section className="panel"><Table headers={['Fecha','Orden','Usuario','Evento','Transición','Motivo']}><tbody>{rows.map(item=><tr key={item.idHistorial}><td>{friendlyDate(item.fechaHora)}</td><td><b>{item.codigoOrden}</b></td><td>{item.nombreUsuario||'Sistema'}</td><td>{item.tipoEvento}</td><td>{item.estadoAnterior||'—'} → {item.estadoNuevo||'—'}</td><td>{item.motivo||'—'}</td></tr>)}{!rows.length&&<EmptyRow columns={6} text="No se encontraron eventos."/>}</tbody></Table></section>}</>
}
function Status({ value }: { value?: string | boolean }) { return <span className={`status ${statusTone(value)}`}>{statusLabel(value)}</span> }; function Table({ headers, children }: { headers: string[]; children: React.ReactNode }) { return <div className="table-wrap"><table><thead><tr>{headers.map((x) => <th key={x}>{x}</th>)}</tr></thead>{children}</table></div> }; function Empty({ text }: { text: string }) { return <p className="empty">{text}</p> }; function EmptyRow({ columns, text }: { columns: number; text: string }) { return <tr><td colSpan={columns}><Empty text={text} /></td></tr> }; function Loading() { return <div className="loading">Cargando datos del backend…</div> }; function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="modal-backdrop" role="presentation"><section className="modal" role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><button aria-label="Cerrar" onClick={onClose}>×</button></header>{children}</section></div> }
